from collections import deque

def components(g):
    h, w = len(g), len(g[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == max(set(x for row in g for x in row), key=lambda x: sum(row.count(x) for row in g)) or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            yield color,cells

def transform(grid):
    g=[row[:] for row in grid]
    # The long L-shaped component is the paint-color key.
    bg=max(set(x for row in g for x in row), key=lambda x: sum(row.count(x) for row in g))
    comps=list(components(g))
    marker=None
    for color,cells in comps:
        if color==bg or len(cells)<7: continue
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        h,w=max(rs)-min(rs)+1,max(cs)-min(cs)+1
        # choose the conspicuous elongated corner/L component
        if h>=5 and w>=4 and len(cells)>=h+w-1:
            if marker is None or len(cells)>len(marker[1]): marker=(color,cells)
    if marker:
        key=marker[0]
        # Recolor the isolated L-triomino matching the clue's corner motif.
        for color,cells in comps:
            if color==bg or color==key or len(cells)!=3: continue
            rs=[r for r,c in cells]; cs=[c for r,c in cells]
            if max(rs)-min(rs)==1 and max(cs)-min(cs)==1:
                if len(set(cells))==3:
                    for r,c in cells: g[r][c]=key
                    break
    return g
